const STY = (bg) => `position:absolute;left:120px;width:700px;height:140px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);background:${bg};color:#0b1020;font-family:inherit;font-weight:800;line-height:1.1;opacity:0;`;
const B1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const B2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;

let g = '';
for(let i=0; i<41; i++) {
  const x = 175 + (i % 7) * 85;
  const y = 215 + Math.floor(i / 7) * 85;
  g += `<rect id="r${i}" x="${x}" y="${y}" width="70" height="70" rx="18" fill="#ffffff" opacity="0.1" />`;
}

root.innerHTML = `
  <div id="c0" style="${STY(B1)}top:45px;font-size:46px;">VOTER REGULATION</div>
  <svg style="position:absolute;width:940px;height:1060px;">${g}</svg>
  <div id="st" style="position:absolute;top:765px;width:100%;text-align:center;color:#ffffff;font-size:54px;font-weight:900;opacity:0;letter-spacing:-1px;">0 / 41 APPROVED</div>
  <div id="c1" style="${STY(B2)}top:875px;font-size:46px;">DATA CENTER LIMITS</div>
`;

const card0 = root.querySelector('#c0');
const card1 = root.querySelector('#c1');
const stats = root.querySelector('#st');
const rects = Array.from({length: 41}, (_, i) => root.querySelector('#r' + i));

function frame(t, p, d) {
  const s1 = spr(t, 0.1, 0.8, 12);
  card0.style.opacity = s1;
  card0.style.transform = `translateY(${lerp(20, 0, s1)}px)`;

  let approvedCount = 0;
  rects.forEach((r, i) => {
    const start = 0.6 + i * 0.05;
    const p_rect = clamp((t - start) * 8);
    if (p_rect > 0) {
      r.setAttribute('opacity', lerp(0.1, 1, p_rect));
      if (p_rect > 0.5) {
        if (i < 40) {
          r.setAttribute('fill', 'var(--acc)');
          approvedCount++;
        } else {
          r.setAttribute('fill', 'var(--acc2)');
        }
      }
    }
  });

  const statsVisible = clamp((t - 0.5) * 2);
  stats.style.opacity = statsVisible;
  stats.textContent = `${approvedCount} / 41 APPROVED`;

  const s2 = spr(t, 3.2, 0.8, 12);
  card1.style.opacity = s2;
  card1.style.transform = `translateY(${lerp(20, 0, s2)}px)`;

  // Hold perfectly still after p=0.55
  if (p > 0.55) {
    stats.style.opacity = 1;
    card0.style.opacity = 1;
    card1.style.opacity = 1;
    card0.style.transform = 'translateY(0px)';
    card1.style.transform = 'translateY(0px)';
    stats.textContent = '40 / 41 APPROVED';
    rects.forEach((r, i) => {
       r.setAttribute('opacity', 1);
       r.setAttribute('fill', i < 40 ? 'var(--acc)' : 'var(--acc2)');
    });
  }
}
